      "verification_notes": "Saltanatın kaldırılması bir kanunla değil, TBMM’nin 1 Kasım 1922 tarihli 308 sayılı Heyet-i Umumiye Kararı (kararname) ile gerçekleşmiştir. Karar, 16 Mart 1920’den itibaren İstanbul hükûmet şeklinin tarihe intikal ettiğini hükme bağlamış; saltanatı ilga ederken hilafeti Osmanlı hanedanına bırakmıştır. TBMM 18 Kasım 1922 tarihli gizli oturumda (162 oydan 148’i ile) Abdülmecid Efendi’yi halife seçmiş, seçim Gazi Mustafa Kemal Paşa’nın 19 Kasım 1922 tarihli telgrafıyla resmen bildirilmiştir.",
