      "verification_notes": "13 Ekim 1923 tarihli Ankara kararı bir kanun teklifi olarak sunulmuşsa da TBMM fihristlerinde 27 numaralı Meclis Kararı (“Ankara Şehrinin Makarr-ı İdare İttihazı Hakkında”) olarak yer almış ve ilk kez 20 Nisan 1924 Anayasası’nın 2. maddesiyle anayasa hükmü hâline gelmiştir. 364 sayılı Kanun 29 Ekim 1923’te kabul edilmiş; dönemin Resmî Ceride’sinin (10 Eylül 1923’ten 17 Aralık 1927’ye dek Resmî Ceride, ardından T.C. Resmî Gazete) 4 Kasım 1923 tarihli nüshasında yayımlanmıştır. Ankara İmar Planı hazırlığı 1927’de başlatılıp 1928’de sınırlı yarışmayla Hermann Jansen’e verilmiş, Bakanlar Kurulunca 23 Temmuz 1932’de onaylanmıştır.",
