          "type": "kurumsal_ansiklopedi",
          "url": "https://ataturkansiklopedisi.gov.tr/detay/940/Halifeli%C4%9Fin-Kald%C4%B1r%C4%B1lmas%C4%B1-(3-Mart-1924)",
          "note": "Şeyh Saffet Efendi önergesini, 431 ve 429 sayılı Kanunların 3 Mart 1924 kabulünü, hanedan mülklerinin devrini ve Erkân-ı Harbiye-i Umumiye’nin kabineden ayrılışını doğrular."
