      "title": "Anayasa’da Laiklik Süreci ve Altı İlke",
      "date_display": "10 Nisan 1928 – 5 Şubat 1937",
      "year": 1928,
      "effective_date": "10 Nisan 1928 kabul / 14 Nisan 1928 RG 863 (1222 sayılı Kanun) ve 5 Şubat 1937 kabul / 13 Şubat 1937 RG 3533 (3115 sayılı Kanun)",
