      "verification_notes": "1222 sayılı Kanun 10 Nisan 1928’de kabul edilmiş, 14 Nisan 1928 tarihli ve 863 sayılı Resmî Gazete’de yayımlanarak yürürlüğe girmiştir (yalnızca 2. maddeyi değil 16, 26 ve 38. maddeleri de değiştirmiştir). 3115 sayılı Kanun ise 5 Şubat 1937’de kabul edilip 13 Şubat 1937 tarihli ve 3533 sayılı Resmî Gazete’de yayımlanmıştır; bazı ikincil özetlerde görülen farklı gün kayıtları (3 Şubat veya 10 Aralık gibi) hatalıdır.",
