      "date_display": "8 Nisan 1924 – 1 Mayıs 1924",
      "year": 1924,
      "effective_date": "8 Nisan 1924 (kabul) / 26 Nisan 1924 (Resmî Ceride / Resmî Gazete yayımı) / 1 Mayıs 1924 (yürürlük)",
