      "verification_notes": "743 sayılı Kanun 17 Şubat 1926’da kabul edilmiş, 4 Nisan 1926 tarihli ve 339 sayılı Resmî Ceride’de (Resmî Gazete) yayımlanmış, 4. maddesi uyarınca altı ay sonra 4 Ekim 1926’da yürürlüğe girmiştir. 864 sayılı Tatbikat Kanunu 29 Mayıs 1926’da kabul edilip 19 Haziran 1926 tarihli ve 402 sayılı Resmî Ceride’de yayımlanmıştır. Kanun’un 152–154. maddeleri evlilik birliğinin reisliği ve temsilini kocaya verirken, kadının meslek ve sanat icrasını koca iznine bağlayan hüküm 159. maddede yer almıştır (159. madde AYM’nin 29 Kasım 1990 tarihli kararıyla iptal edilmiş, aile reisliği hükümleri 2002’de 4721 sayılı Kanun’la kaldırılmıştır).",
