      "title": "Türk Ceza Kanunu, Borçlar Kanunu ve Ceza Muhakemeleri Usulü (CMUK)",
      "date_display": "1 Mart 1926 – 20 Ağustos 1929",
      "year": 1926,
      "effective_date": "1 Temmuz 1926 (765 sayılı TCK) / 4 Ekim 1926 (818 sayılı Borçlar Kanunu) / 20 Ağustos 1929 (1412 sayılı CMUK)",
      "law_ref": "765 sayılı Türk Ceza Kanunu, 818 sayılı Borçlar Kanunu ve 1412 sayılı Ceza Muhakemeleri Usulü Kanunu",
      "institutions": [
        "Türkiye Büyük Millet Meclisi",
        "Adliye Vekâleti",
        "Ceza ve Borçlar Hukuku İhtisas Komisyonları"
      ],
      "before": "1858 tarihli Ceza Kanunname-i Hümayunu ile 1879 tarihli Usul-i Muhakemât-ı Cezaiye Kanunu Cumhuriyet’in yargı ve ceza politikası ihtiyaçlarını karşılamakta yetersiz kalıyordu. Borçlar ve sözleşmeler alanı ise hâlâ Mecelle’nin kısmi hükümlerine bağlı olduğundan, 743 sayılı Medenî Kanun ile uyumlu laik bir borçlar hukuku ve çağdaş ceza yargılaması usulü zorunluydu.",
      "action": "1889 İtalyan Zanardelli Kanunu esas alınarak hazırlanan 765 sayılı Türk Ceza Kanunu 1 Mart 1926’da kabul edildi, 13 Mart 1926’da Resmî Ceride’de (Resmî Gazete) yayımlandı ve 591. maddesi gereğince 1 Temmuz 1926’da yürürlüğe girdi. İsviçre Borçlar Kanunu’ndan uyarlanan 818 sayılı Borçlar Kanunu 22 Nisan 1926’da kabul edilip 8 Mayıs 1926’da yayımlandı ve 4 Ekim 1926’da Medenî Kanun ile birlikte yürürlüğe kondu. 1877 Alman ceza usul yasasını temel alan 1412 sayılı CMUK ise 4 Nisan 1929’da kabul edilerek 20 Nisan 1929’da Resmî Gazete’de yayımlandı ve 20 Ağustos 1929’da yürürlüğe girdi.",
      "impact": "Üç temel kod ile Türkiye’de suçta ve cezada kanunilik, laik borç ilişkileri ve sözleşme özgürlüğü ile çağdaş ceza muhakemesi güvenceleri kurumsallaştı; bu yasalar 2005 ve 2012 yıllarına dek yaklaşık seksen yıl yürürlükte kaldı. Buna karşılık 765 sayılı TCK, özellikle 1936’daki değişikliklerden başlayarak siyasal suç tanımları bakımından sertleştirildi ve dönemin siyasal kısıtlamalarının hukuki aracı hâline de getirildi.",
      "key_figures": [
        "Gazi Mustafa Kemal Paşa",
        "Mahmut Esat (Bozkurt)",
        "Mehmet İhsan Bey",
        "Mustafa Fevzi (Sarhan)"
      ],
