      "verification_notes": "İkincil kaynaklarda 765 sayılı TCK ve 818 sayılı Borçlar Kanunu’nun Resmî Ceride (Resmî Gazete) yayım tarihleri (13 Mart 1926 / Sayı: 320 ve 8 Mayıs 1926 / Sayı: 366) zaman zaman fiilî yürürlük tarihleriyle karıştırılmaktadır; oysa TCK m. 591 gereği 1 Temmuz 1926’da, Borçlar Kanunu Medenî Kanun ile eş zamanlı olarak 4 Ekim 1926’da, 1412 sayılı CMUK (20 Nisan 1929 RG Sayı: 1172) ise yayımından 4 ay sonra 20 Ağustos 1929’da yürürlüğe girmiştir. 1936’da 11 Haziran 1936 tarihli 3038 sayılı Kanun başta olmak üzere yapılan değişikliklerle devlet şahsiyetine ve kamu düzenine karşı suçlar ağırlaştırılmıştır.",
