      "institutions": [
        "Türkiye Büyük Millet Meclisi",
        "Adliye Vekâleti",
        "Ticaret Vekâleti"
      ],
      "before": "1850 tarihli Kanunname-i Ticaret, 1863 tarihli Ticaret-i Bahriye ve 1879 tarihli Usul-i Muhakeme-i Hukukiye metinleri, kapitülasyonların kalktığı Cumhuriyet ekonomisinin şirketleşme, kabotaj ve alacak takibi gereksinimlerini karşılayamıyordu. Medenî ve Borçlar Kanunlarının uygulanabilmesi için medeni yargılama usulü ile icra-iflas hukukunun da yenilenmesi gerekiyordu.",
      "action": "865 sayılı Ticaret Kanunu 29 Mayıs 1926’da kabul edilip 4 Ekim 1926’da yürürlüğe girdi; buna 13 Mayıs 1929 tarihli 1440 sayılı Kanun ile Alman Ticaret Kanunu’ndan alınan Deniz Ticareti Kitabı eklendi (yürürlük 21 Kasım 1929). İsviçre’nin Neuchâtel kantonu usul yasasını esas alan 1086 sayılı HUMK 18 Haziran 1927’de kabul edilip 4 Ekim 1927’de yürürlüğe kondu. İsviçre’den uyarlanan 18 Nisan 1929 tarihli 1424 sayılı İcra ve İflas Kanunu (yürürlük 4 Eylül 1929) ise uygulamadaki aksaklıklar nedeniyle 9 Haziran 1932’de kabul edilen 2004 sayılı İcra ve İflas Kanunu (yürürlük 4 Eylül 1932) ile değiştirildi.",
      "impact": "Özel hukuk kodifikasyonu ticaret, deniz taşımacılığı, yargılama usulü ve cebrî icra alanlarında tamamlanarak piyasa ve kredi güvenliği için yeknesak kurallar sağlandı; 2004 sayılı İİK günümüzde de temel icra mevzuatı olmayı sürdürmektedir. Buna karşın 865 sayılı Ticaret Kanunu birden fazla ülke mevzuatından derlendiği için Borçlar Kanunu ile yer yer kavram uyumsuzluğu yaşadı ve 1956’da 6762 sayılı Kanun’la yenilendi.",
      "key_figures": [
        "Gazi Mustafa Kemal Paşa",
        "Mahmut Esat (Bozkurt)",
        "Ali Cenani",
        "Yusuf Kemal (Tengirşenk)"
      ],
