      "verification_notes": "İkincil kaynaklarda sıkça karıştırılan iki nokta vardır: (1) 832 sayılı Sayıştay Kanunu Atatürk dönemine değil 21 Şubat 1967 tarihine aittir; Atatürk dönemindeki temel teşkilat yasası 16 Haziran 1934 kabul, 25 Haziran 1934 Resmî Gazete (Sayı: 2735) ve m. 86 gereği 1 Haziran 1934 yürürlük tarihli 2514 sayılı Divân-ı Muhâsebât Kanunu’dur. (2) TBMM kayıtlarında 1426 sayılı Vilayet İdaresi Kanunu’nun kanun tarihi 24 Nisan 1929 (Resmî Gazete ve yürürlük 5 Mayıs 1929, Sayı: 1184) olarak geçerken, bazı akademik yayınlarda Meclis Genel Kurulu oylama günü olan 18 Nisan 1929 tarihi kabul günü olarak anılır. 669 sayılı Kanun ise 23 Kasım 1925’te kabul edilip 7 Aralık 1925 tarihli ve 238 sayılı Resmî Ceride’de (Resmî Gazete) yayımlanmıştır.",
