      "verification_notes": "430 sayılı Kanun 3 Mart 1924’te kabul edilmiş, 6 Mart 1924 tarihli ve 63 sayılı Resmî Ceride’de yayımlanarak yürürlüğe girmiştir. 1921 Maarif Kongresi’nin başlangıcı 15 Temmuz, Mustafa Kemal Paşa’nın açılış nutku 16 Temmuz 1921 tarihli olup Gazilik ünvanı henüz 19 Eylül 1921’de (153 sayılı Kanun) verilmediğinden Temmuz 1921 anlatımında yalnızca “Mustafa Kemal Paşa” kullanılmıştır. Medreselerin fiilen kapatılması kanun metninde değil, Maarif Vekili Vasıf Bey’in 11 Mart 1924 tarihli genelgesiyle gerçekleşmiştir.",
