      "verification_notes": "789 sayılı Kanun 22 Mart 1926’da kabul edilmiş, 3 Nisan 1926 tarihli ve 338 sayılı Resmî Ceride’de yayımlanmıştır (bazı ikincil kaynaklarda 23 Mart olarak geçse de TBMM tutanak ve kanun metni 22 Mart 1926’dır). Kuruluşunda Talim ve Terbiye Dairesi olan birim 1933’te Millî Talim ve Terbiye Dairesi, sonrasında Talim ve Terbiye Kurulu Başkanlığı adını almıştır; maarif eminlikleri ise 29 Haziran 1931 tarihli ve 1834 sayılı Kanun’la kaldırılmıştır.",
