      "verification_notes": "1353 sayılı Kanun 1 Kasım 1928’de kabul edilmiş, 3 Kasım 1928 tarihli ve 1030 sayılı Resmî Gazete’de yayımlanmıştır. Millet Mektepleri Talimatnamesi Bakanlar Kurulu’nca 11 Kasım 1928’de onaylanmış, 24 Kasım 1928’de Resmî Gazete’de yayımlanarak yürürlüğe girmiştir; fiilî öğretim 1 Ocak 1929’da başlamıştır. 1935 nüfus sayımında 6 yaş ve üzeri nüfusta resmî okuryazarlık oranı %19,25 (erkeklerde %29,35, kadınlarda %9,81) olarak ölçülürken, Atatürk Ansiklopedisi ve bazı eğitim tarihi çalışmalarında 7+ yaş / karşılaştırmalı seriler üzerinden %19,9–20,4 (kadınlarda %10,5) değerleri aktarılmaktadır.",
