      "year": 1935,
      "effective_date": "20 Haziran 1933 (2291 sayılı Kanun) / 15 Haziran 1935 (2777 sayılı Kanun) / 22 Haziran 1935 (2795 sayılı Kanun) / 9 Ocak 1936 (DTCF açılışı)",
      "law_ref": "2291, 2777 ve 2795 sayılı Kanunlar",
