      "before": "Selçuklu ve Osmanlı dönemlerinde dinî, sosyal ve vakıf işlevleri bulunan tarikatlar, tekke ve zaviyeler, zamanla hukukî denetim dışında kalan özerk odaklara dönüşmüştü. 1925 yılındaki Şeyh Sait İsyanı sonrasında çıkarılan Takrir-i Sükûn Kanunu ortamında Gazi Mustafa Kemal Paşa, 30 Ağustos 1925’teki Kastamonu nutkunda Cumhuriyet’in şeyhler ve dervişler ülkesi olamayacağını açıkladı. Hükûmet 2 Eylül 1925 tarihli kararnameyle tekkelerin kapatılması yönünde ilk idari adımı attı.",
      "action": "Bakanlar Kurulunun hazırladığı tasarıyı görüşen TBMM, 30 Kasım 1925’te 677 sayılı Kanun’u kabul etti; yasa 13 Aralık 1925 tarihli ve 243 sayılı Resmî Gazete’de yayımlanarak yürürlüğe girdi. Kanunla tüm tekke ve zaviyeler kapatılırken usulüne uygun biçimde cami veya mescit olarak kullanılanlar açık bırakıldı. Ayrıca tarikatlar ile şeyhlik, dervişlik, müritlik, dedelik, seyitlik, çelebilik, babalık, halifelik gibi ünvanlar; falcılık, büyücülük, üfürükçülük ve nüshacılık yasaklandı, tüm türbeler kapatılarak türbedarlıklar kaldırıldı.",
      "impact": "Yasayla tarikatların kamusal ve hukukî varlığına son verildi; arşiv verileri ve akademik incelemelerde bu süreçte 773 tekke ile 905 türbenin kapatıldığı aktarılmaktadır. Kapatılan yapıların bir bölümü Maarif Vekâleti’ne veya yerel idarelere devredilerek okul, kütüphane ya da müzeye dönüştürüldü. Kanun Anayasa’nın 174. maddesiyle güvence altına alınmakla birlikte, tarikat yapıları yeraltında veya gayriresmî ağlar biçiminde varlığını kısmen sürdürdü; 1 Mart 1950 tarihli 5566 sayılı Kanun ile de Türk büyüklerine ve sanat değerine sahip türbelerin bakanlık/Bakanlar Kurulu izniyle ziyarete açılmasına imkân tanındı.",
