      "verification_notes": "Riyaset-i Cumhur Musiki Heyeti 25 Haziran 1932’de Maarif Vekâletine bağlanmış, 1933 yeniden yapılanmasıyla Riyaset-i Cumhur Filarmoni Orkestrası adını almıştır. Darülbedayi 1931’de İstanbul Belediyesince Şehir Tiyatrosu olarak yapılandırılmış, 1934’te İstanbul Belediyesi Şehir Tiyatroları adı yerleşmiştir. Musiki Muallim Mektebi 1 Kasım 1924’te açılmış, 1936’da Ankara Devlet Konservatuvarı bünyesinde yapılandırıldıktan sonra öğretmen yetiştirme kolu 1938’de Gazi Eğitim Enstitüsüne devredilmiştir. İstanbul Resim ve Heykel Müzesi için 18 Temmuz 1937 kuruluş kararı ve 20 Eylül 1937 resmî açılış tarihi birlikte anılır. 3530 sayılı Kanun 29 Haziran 1938’de kabul edilmiş, 16 Temmuz 1938 tarihli ve 3961 sayılı Resmî Gazete’de yayımlanarak yürürlüğe girmiştir.",
