      "before": "Medenî Kanun ile aile ve yurttaşlık hukukunda önemli kazanımlar elde edilmesine karşın kadınlar yerel ve genel seçimlerde oy kullanma ve aday olma hakkına henüz sahip değildi. Türk Kadınlar Birliği’nin 1924’ten itibaren sürdürdüğü siyasal hak talepleri çeşitli Meclis oturumlarında reddedilmişti. Kent yönetimlerinin modernleştirilmesi gündeme geldiğinde kadınların yerel demokrasiye katılması gereği yeniden tartışmaya açıldı.",
      "action": "Cumhurbaşkanı Gazi Mustafa Kemal Paşa’nın desteği, Afet (İnan) Hanım’ın 1930 başındaki toplumsal hazırlık çalışmaları ve Dahiliye Vekili Şükrü Kaya’nın önerisiyle hazırlanan 1580 sayılı Belediye Kanunu, 3 Nisan 1930’da TBMM’de kabul edildi ve 14 Nisan 1930 tarihli, 1471 sayılı Resmî Gazete’de yayımlandı. Kanunun 23 ve 24. maddeleriyle 18 yaşını bitiren kadınlara belediye seçimlerinde oy verme, 25 yaşını bitirenlere ise belediye meclislerine seçilme hakkı tanındı.",
      "impact": "1930 sonbaharındaki belediye seçimlerinde –Cumhuriyet Halk Fırkası ile Serbest Cumhuriyet Fırkası arasındaki rekabet ortamında– kadınlar Türkiye’de ilk kez sandık başına giderek oy kullandı ve aday oldu. İstanbul’da Nakiye Elgün, Safiye Hüseyin Elbi, Latife Bekir ve Rana Hanım ile İzmir’de Hasane Nalan ve Benal Nevzat (Arıman) belediye meclislerine seçildi. Artvin’in Yusufeli ilçesine bağlı Kılıçkaya (eski adıyla Ersis) beldesinde 1930’da seçilen Sadiye Hanım (1930–1932) Türkiye’nin ilk kadın belde belediye başkanı oldu; ilk kadın il belediye başkanı ise Eylül 1950’de Demokrat Parti listesinden Mersin Belediye Başkanı seçilen Fatma Müfide İlhan’dır.",
