      "before": "Kadınlar Halk Fırkası girişiminin onaylanmaması üzerine 7 Şubat 1924’te Nezihe Muhiddin başkanlığında kurulan Türk Kadınlar Birliği (TKB), 1927’den itibaren Latife Bekir (Çeyrekbaşı) yönetiminde siyasal haklar ve toplumsal eşitlik için çalıştı. Uluslararası Kadınlar Birliği’ne (IAW) üye olan dernek, 5 Aralık 1934’te milletvekili seçme-seçilme hakkının tanınmasının ardından büyük bir uluslararası buluşmaya ev sahipliği yapmaya hazırlandı.",
      "action": "Cumhurbaşkanı Atatürk’ün de desteklediği organizasyonla 12. Uluslararası Kadınlar Birliği Kongresi, 18–24 Nisan 1935 tarihleri arasında (kapanış ve gezi etkinlikleriyle 26 Nisan’a dek) İstanbul’da Yıldız Sarayı’nda toplandı. 30’u aşkın ülkeden yüzlerce delegenin katıldığı kongrede Türkiye’yi yeni seçilen kadın milletvekillerinin de yer aldığı 23 kişilik heyet temsil etti; eşit yurttaşlık, çalışma hakları ve Avrupa’da yükselen faşizm karşısında barış başlıkları tartışıldı, Posta ve Telgraf İdaresi tarafından 15 parçalık özel anı pulu serisi bastırıldı.",
      "impact": "Müslüman çoğunluklu bir ülkede toplanan ilk uluslararası kadın kongresi olan Yıldız Sarayı buluşması, Türkiye’deki hukuk ve siyasal hak reformlarını dünya kamuoyuna tanıttı. Bununla birlikte kongrenin hemen ardından, 10 Mayıs 1935’te toplanan Türk Kadınlar Birliği kongresinde Başkan Latife Bekir, kadınların bütün haklarına kavuştuğu ve derneğin amacına ulaştığı gerekçesiyle fesih önergesi verdi ve TKB kendi kendini feshetti. Bu karar, erken Cumhuriyet döneminde bağımsız kadın örgütlenmesinin tek parti devlet yapısı içinde 1949’a dek sona ermesi bakımından tarih yazımında önemli bir dönüm noktası olarak değerlendirilir.",
