      "before": "Osmanlı Devleti’nin son döneminde kapitülasyonlar ve 1881 tarihli Muharrem Kararnamesi ile kurulan Düyun-ı Umumiye İdaresi, devletin gümrük, vergi ve maliye egemenliğini ağır biçimde kısıtlamıştı. Millî Mücadele’nin ardından ülke sanayisi yetersiz, dış ticaret açıkları yüksek, köylü nüfus ise tarımsal üründen onda bir oranında alınan ve iltizam usulüyle toplanan aşar vergisi altında ezilmekteydi. Lozan görüşmelerinin kesintiye uğradığı dönemde yeni devletin iktisat programını belirlemek acil bir zorunluluk doğurdu.",
      "action": "17 Şubat – 4 Mart 1923 tarihlerinde Gazi Mustafa Kemal Paşa’nın açış konuşması ve Kâzım Karabekir Paşa’nın başkanlığında, çiftçi, tüccar, sanayici ve işçi temsilcilerinin katılımıyla İzmir İktisat Kongresi toplanarak 12 maddelik Misak-ı İktisadî kabul edildi. Ardından 24 Temmuz 1923’te imzalanan Lozan Barış Antlaşması’nın 28. maddesiyle kapitülasyonlar tüm sonuçlarıyla kaldırıldı; Düyun-ı Umumiye İdaresinin malî denetim yetkisi sona erdirilerek Osmanlı borçları ayrılan devletler arasında paylaştırıldı. Kongrede çiftçilerin başlıca talebi olan aşarın kaldırılması ise 17 Şubat 1925 tarihli ve 552 sayılı Kanun ile yasalaştırılarak köylünün geçimlik tüketimi vergiden muaf tutuldu.",
      "impact": "Kapitülasyonların ve Düyun-ı Umumiye vesayetinin tasfiyesi, Türkiye’nin siyasal bağımsızlığını malî ve hukukî egemenlikle tamamlamasını sağladı; bununla birlikte Lozan’a ek Ticaret Sözleşmesi gereği gümrük tarifelerindeki kısıtlar 1929’a dek sürdü. Devlet bütçe gelirlerinin yaklaşık üçte birini oluşturan aşardan vazgeçilmesi kırsal kesimin vergi yükünü hafifleterek küçük üreticinin pazar ekonomisine yönelimini hızlandırdı. Kamu maliyesinde doğan gelir açığı ise arazi, hayvan ve dolaylı tüketim vergilerindeki düzenlemelerle dengelenmeye çalışıldı.",
