      "date_display": "26 Ağustos 1924 – 23 Mayıs 1938",
      "year": 1930,
      "effective_date": "26 Ağustos 1924 (İş Bankası) / 19 Nisan 1925 (633 sayılı Kanun) / 3 Haziran 1926 RG (844 sayılı Kanun) / 1 Ekim 1929 yürürlük (1499 sayılı Kanun) / 25 Şubat 1930 RG (1567 sayılı Kanun) / 11 Haziran 1930 kabul – 30 Haziran 1930 RG – 3 Ekim 1931 açılış (1715 sayılı TCMB) / 23 Mayıs 1938 faaliyet (2284 sayılı Kanun)",
      "law_ref": "633, 844, 1499, 1567, 1715 ve 2284 sayılı Kanunlar",
