      "before": "Cumhuriyet’in ilk yıllarında bankacılık ve kredi piyasası büyük ölçüde Osmanlı Bankası gibi yabancı sermayeli kuruluşların elindeydi; para basma imtiyazı da devlete ait değildi. Lozan’a ek Ticaret Sözleşmesi nedeniyle Türkiye 1929 yılına dek eski 1916 Osmanlı gümrük tarifelerini değiştirememiş, yerli sanayiyi dış rekabete karşı koruyamamıştı. 1929 Dünya Ekonomik Bunalımı’nın başlamasıyla döviz kurlarında dalgalanma artınca ulusal para ve kredi egemenliğinin kurumsallaştırılması zorunlu hâle geldi.",
      "action": "İzmir İktisat Kongresi kararları doğrultusunda 26 Ağustos 1924’te Gazi Mustafa Kemal Paşa’nın girişimiyle Türkiye İş Bankası, 19 Nisan 1925 tarihli 633 sayılı Kanun’la Sanayi ve Maadin Bankası, 3 Haziran 1926’da yayımlanan 844 sayılı Kanun’la da Emlâk ve Eytam Bankası kuruldu. Lozan kısıtlarının bitimiyle 8 Haziran 1929 kabul ve 1 Ekim 1929 yürürlük tarihli 1499 sayılı Gümrük Tarifesi Kanunu korumacı dış ticaret rejimini başlattı. 20 Şubat 1930 kabul ve 25 Şubat 1930 yayım tarihli 1567 sayılı Türk Parasının Kıymetini Koruma Hakkında Kanun’un ardından, 11 Haziran 1930 kabul ve 30 Haziran 1930 yayım tarihli 1715 sayılı Kanun’la Türkiye Cumhuriyet Merkez Bankası kurularak 3 Ekim 1931’de açıldı; 8 Haziran 1933 tarihli 2284 sayılı Kanun’la öngörülen Halk Bankası da 23 Mayıs 1938’de faaliyete geçti.",
      "impact": "Bu kurumsal zincir sayesinde banknot ihracı ve kambiyo denetimi millî kurumlara geçerek para politikasında dışa bağımlılık sona erdi; koruyucu gümrük tarifeleri yerli tüketim sanayisinin doğuşuna zemin hazırladı. Konut, imar ve sanayi kredileri ulusal ve kamusal bankalar aracılığıyla yönlendirildi. Bununla birlikte Sanayi ve Maadin Bankası sermaye darlığı ve işletmecilik güçlükleri nedeniyle 1932’de tasfiye edilerek yerini Sanayi Ofisi ile 1933’te Sümerbank’a bıraktı; Halk Bankası ise 1938’de sınırlı şube ve halk sandıklarıyla hizmete başlayabildi.",
