      "date_display": "22 Nisan 1924 – 31 Mayıs 1927",
      "year": 1926,
      "effective_date": "22 Nisan 1924 kabul / 24 Mayıs 1924 yayım (506 sayılı Kanun) / 19 Nisan 1926 kabul / 1 Temmuz 1926 yürürlük (815 sayılı Kanun) / 22 Mayıs 1927 kabul / 31 Mayıs 1927 yayım (1042 sayılı Kanun)",
      "law_ref": "506 sayılı Anadolu Demiryollarının Mubayaasına Dair Kanun, 815 sayılı Kabotaj Kanunu ve 1042 sayılı Devlet Demiryolları Kanunu",
