      "before": "Osmanlı döneminden devralınan kara suları ve liman taşımacılığı büyük ölçüde yabancı şirketlerin ve yabancı bayraklı gemilerin elindeydi; liman hizmetleri ve kılavuzlukta da yerli denizcilerin payı sınırlıydı. Ülke içindeki 4.112 kilometrelik demir yolu ağının 3.756 kilometresi yabancı imtiyazlı şirketlerce işletilmekte, hatlar iç pazar bütünleşmesinden çok limanlara ham madde taşımaya göre uzanmaktaydı. Ankara merkezli bütünleşik bir iç pazar ve ulusal ulaşım egemenliği için deniz ve demir yolu ağlarının millîleştirilmesi gerekiyordu.",
      "action": "Nafia Vekâleti ve TBMM’nin yasama adımlarıyla, 22 Nisan 1924’te kabul edilip 24 Mayıs 1924’te yayımlanan 506 sayılı Kanun uyarınca Anadolu-Bağdat hatları ile Haydarpaşa Limanı’nın satın alınması ve devletçe işletilmesi kararlaştırıldı. Ardından 19 Nisan 1926’da kabul edilen ve 1 Temmuz 1926’da yürürlüğe giren 815 sayılı Kabotaj Kanunu ile Türk limanları arasında yük ve yolcu taşımacılığı, kılavuzluk ve denizcilik meslekleri yalnız Türk bayrağına ve yurttaşlara tanındı. 22 Mayıs 1927’de kabul edilip 31 Mayıs 1927’de Resmî Gazete’de yayımlanan 1042 sayılı Kanun ile de tüm hat ve liman yönetimleri Devlet Demir Yolları ve Limanları İdare-i Umumiyesi çatısı altında birleştirildi.",
      "impact": "Kabotaj hakkının kazanılmasıyla deniz taşımacılığı ve liman hizmetleri yabancı tekellerden arındırılarak yerli denizcilik ve deniz eğitimi gelişmeye başladı; 1 Temmuz günü Kabotaj Bayramı olarak benimsendi. Demir yollarında ise yabancı şirket hatlarının satın alımı sürerken 1923–1938 arasında yaklaşık 2.815–3.000 kilometre yeni hat döşenerek Kayseri (1927), Sivas (1930), Malatya (1931) ve Diyarbakır (1935) birbirine bağlandı. Yüksek yatırım maliyeti nedeniyle inşa süreci bütçe kaynakları ve iç borçlanmalarla uzun yıllara yayıldı; kara yolu ağı ise bu dönemde ikincil konumda kaldı.",
