      "before": "1920’li yılların ortasında Türkiye ekonomisi büyük ölçüde geleneksel tarım yöntemlerine dayanıyor, kurak İç Anadolu’da modern tarım işletmeciliği örneği bulunmuyor, özel sanayi girişimleri ise sermaye ve teknik donanım eksikliği nedeniyle gelişemiyordu. Küçük çiftçiler tefeci borçlarıyla karşı karşıya kalırken, ormanlar düzensiz kesim yüzünden tahrip edilmekteydi. 1929 Bunalımı’yla buğday fiyatlarının sert biçimde düşmesi üreticiyi koruyacak kurumsal bir alım mekanizmasını ayrıca zorunlu kıldı.",
      "action": "Gazi Mustafa Kemal Paşa, 5 Mayıs 1925’te Ankara’nın bataklık ve kıraç arazilerinde örnek çiftlik ve ağaçlandırma alanı olarak Gazi Orman Çiftliği’ni kurdu; özel girişimi özendirmek amacıyla 28 Mayıs 1927’de kabul edilip 15 Haziran 1927’de yayımlanan 1055 sayılı Teşvik-i Sanayi Kanunu ile arazi tahsisi ve vergi-gümrük muafiyetleri getirildi. Çiftçi finansmanı için 1929’da 1470 sayılı, 21 Ekim 1935 kabul ve 2 Kasım 1935 yayım tarihli 2836 sayılı Kanunlarla Tarım Kredi Kooperatifleri teşkilatlandırıldı. 8 Şubat 1937 kabul ve 1 Haziran 1937 uygulama tarihli 3116 sayılı Orman Kanunu ormanları devlet korumasına aldı; Cumhurbaşkanı Atatürk 11 Haziran 1937’de çiftliklerini Hazineye bağışladı ve 24 Haziran 1938 kabul, 13 Temmuz 1938 yayım tarihli 3491 sayılı Kanun’la Toprak Mahsulleri Ofisi (TMO) kuruldu.",
      "impact": "Teşvik-i Sanayi Kanunu yerli fabrika sayısında artış sağlasa da 1929 Bunalımı ve sermaye yetersizliği nedeniyle özel sektör büyük sanayi atılımını kendi başına sürükleyemedi; bu sınır devletçilik politikasına geçişi hızlandırdı. Buna karşılık Tarım Kredi Kooperatifleri, 3116 sayılı Kanun’la kurulan teknik ormancılık düzeni, örnek çiftlik uygulamaları (1950’de 5659 sayılı Kanun’la Atatürk Orman Çiftliği adını aldı) ve TMO’nun fiyat istikrarı ile silo altyapısı kırsal üretim ve gıda güvenliğinde kalıcı kurumsal zemin oluşturdu.",
