      "before": "Cumhuriyet’in ilk yıllarında Türkiye, şeker, şişe-züccaciye camı ile kâğıt ve karton gibi en temel tüketim ve kültür ürünlerinin tamamına yakınını dış alımla karşılamaktaydı. Osmanlı döneminde şeker ve kâğıt sanayisi kurmaya yönelik girişimler sermaye, teknik kadro ve ham madde örgütlenmesi eksikliği yüzünden kalıcı olamamıştı. Şeker pancarı tarımını yaygınlaştırmak, yerli silis kumunu değerlendirmek ve yeni harflerle artan okul-matbaa kâğıdı talebini içeriden karşılamak öncelikli hedefler hâline geldi.",
      "action": "5 Nisan 1925 tarihli 601 sayılı Kanun’un ardından, 22 Aralık 1925’te temeli atılan Alpullu Şeker Fabrikası 26 Kasım 1926’da ilk yerli şekeri üretti; Nuri (Şeker) Bey öncülüğündeki Uşak Şeker Fabrikası 17 Aralık 1926’da açıldı ve Eskişehir (1933) ile Turhal (1934) tesislerinin ardından 18 Haziran 1935 tarihli ve 2850 sayılı Bakanlar Kurulu Kararı ile 6 Temmuz 1935’te Türkiye Şeker Fabrikaları A.Ş. kuruldu. Birinci Beş Yıllık Sanayi Planı kapsamında 14 Ağustos 1934’te temeli atılan İş Bankası iştiraki Paşabahçe Şişe ve Cam Fabrikası Haziran–Temmuz 1935’te deneme üretimine geçip 29 Kasım 1935’te Başbakan İsmet İnönü tarafından resmen açıldı. Mehmet Ali Kâğıtçı’nın projelendirdiği Sümerbank İzmit Kâğıt ve Karton Fabrikası (SEKA) da 14 Ağustos 1934’te temeli atılıp 18 Nisan 1936’da ilk kâğıdı üretti ve 6 Kasım 1936’da resmen açıldı.",
      "impact": "1930’ların ikinci yarısına gelindiğinde Türkiye şeker, şişe-züccaciye camı ve temel kâğıt-karton tüketiminin büyük bölümünü yerli üretimle karşılayabilir konuma yükseldi; pancar tarımı ve selüloz üretimi kırsal ekonomiyle sanayi arasında doğrudan bağ kurdu. İzmit tesisleri sonraki yıllarda genişletilerek SEKA adıyla ülkenin basım-yayın ve eğitim altyapısını besledi. Bununla birlikte bu tesislerde makine ve kimi kimyasal girdilerde dış alım bağımlılığı ilk yıllarda sürdü; tam entegre selüloz ve düz cam üretimi sonraki yatırım evrelerinde tamamlanabildi.",
