      "title": "Sıhhat Vekâleti, Salgın Hastalıklarla Mücadele ve Numune Hastaneleri",
      "date_display": "2 Mayıs 1920 – 13 Mayıs 1926",
      "year": 1920,
      "effective_date": "2 Mayıs 1920 (3 sayılı Kanun) / 1 Mayıs 1924 (Numune Hastaneleri) / 13 Mayıs 1926 kabul – 29 Mayıs 1926 Resmî Ceride yayımı (839 sayılı Kanun)",
      "law_ref": "3 sayılı Büyük Millet Meclisi İcra Vekillerinin Suret-i İntihabına Dair Kanun, 90 sayılı Frengi Kanunu ve 839 sayılı Sıtma Mücadelesi Kanunu",
      "institutions": [
        "Sıhhat ve İçtimai Muavenet Vekâleti (Sıhhiye ve Muavenet-i İçtimaiye Vekâleti)",
        "Türkiye Büyük Millet Meclisi",
        "Numune Hastaneleri",
        "Heybeliada Sanatoryumu"
      ],
      "before": "Uzun süren savaş yıllarının ardından Anadolu’da sıtma, tifüs, trahom, verem ve frengi gibi salgınlar halk sağlığını ve nüfus yapısını derinden sarsmıştı. Osmanlı döneminden devralınan sağlık altyapısı son derece yetersizdi; 1923–1924 döneminde ülke genelinde yalnızca 86 civarında sağlık kurumunda yaklaşık 6.437 yatak bulunuyordu. Sağlık örgütlenmesi dağınık bir görünüm sergiliyor, merkezî bir koruyucu hekimlik politikası yürütülemiyordu.",
      "action": "TBMM’nin 2 Mayıs 1920 tarihli ve 3 sayılı Kanunu ile müstakil Sıhhiye ve Muavenet-i İçtimaiye Vekâleti (sonraki kullanımla Sıhhat ve İçtimai Muavenet Vekâleti) kurularak ilk vekil Dr. Adnan (Adıvar) Bey seçildi. Mustafa Kemal Paşa’nın desteklediği ve Dr. Refik (Saydam) Bey’in bakanlığı döneminde şekillenen programla 5 Şubat 1921 tarihli 90 sayılı Kanunla frengi tedavisi ücretsiz kılındı; 1924 bütçe kararıyla Ankara, Sivas, Erzurum ve Diyarbakır’da Numune Hastaneleri ile 1 Kasım 1924’te Heybeliada Sanatoryumu açıldı. 13 Mayıs 1926’da kabul edilip 29 Mayıs 1926 tarihli Resmî Ceride’de yayımlanan 839 sayılı Sıtma Mücadelesi Kanunu ile bataklık kurutma ve ücretsiz kinin dağıtımı yasal güvenceye bağlandı.",
      "impact": "Koruyucu hekimliği öne çıkaran bu kurumsal yapılanma sayesinde salgın hastalıklarla mücadele devletin doğrudan sorumluluğuna girdi; Güneydoğu ve İç Anadolu’da trahom dispanserleri ile gezici ekipler kuruldu. Yataklı tedavi kapasitesi 1935 yılında 176 kuruma ve 13.038 yatağa yükseldi, Numune Hastaneleri taşra hekimliği için uzmanlık merkezlerine dönüştü. Buna karşın 1927’de ülke genelinde yalnızca 1.059 hekimin bulunması (yaklaşık 13.000 kişiye bir hekim), sağlık hizmetlerinin kırsala eşit yayılmasını dönem boyunca sınırlandırdı.",
      "key_figures": [
        "Mustafa Kemal Paşa",
        "Dr. Adnan Adıvar",
        "Dr. Refik Saydam",
        "Dr. Vefik Hüsnü Bulat"
      ],
