      "verification_notes": "Bakanlık 2 Mayıs 1920 tarihli 3 sayılı Kanun ile “Sıhhiye ve Muavenet-i İçtimaiye Vekâleti” adıyla kurulmuş, 1920’lerin sonu ve 1930 tarihli 1593 sayılı Kanun metinlerinde “Sıhhat ve İçtimai Muavenet Vekâleti” biçimi yerleşmiştir. 839 sayılı Sıtma Mücadelesi Kanunu 13 Mayıs 1926’da kabul edilmiş ve 29 Mayıs 1926 tarihli Resmî Ceride’de yayımlanmıştır. 1923–1924 yatak sayılarında farklı tasnifler (tüm resmî/özel kurumlar dâhil 86 kurum–6.437 yatak vs. dar kamu tasnifleri) kaynak notuna yansıtılmıştır.",
