      "before": "Osmanlı İmparatorluğu’ndan devralınan İmalât-ı Harbiye atölyeleri İstanbul’un işgali sırasında tahrip olmuş ya da işlevsiz kalmıştı; kara, hava ve deniz kuvvetlerinin silah, mühimmat, uçak ve gemi onarımı ihtiyaçları büyük ölçüde dış alıma bağımlıydı. İç Anadolu’nun güvenli bölgelerinde entegre bir savunma ve metalürji altyapısı henüz kurulmamıştı.",
      "action": "Millî Mücadele sırasında İstanbul’dan kaçırılan tezgâhların birleştirilmesiyle 1921’de Millî Müdafaa Vekâletine bağlı Askerî Fabrikalar Umum Müdürlüğü teşkilatlandırıldı. Mustafa Kemal Paşa’nın ve hükûmetin stratejik sanayi politikası çerçevesinde, Türk Tayyare Cemiyeti ile Alman Junkers ortaklığında 1925’te kurulan TOMTAŞ’ın Kayseri Tayyare Fabrikası 6 Ekim 1926’da açıldı; ortaklıktaki mali anlaşmazlıklar nedeniyle 1928’de tasfiye edilerek devletleştirildi. Aynı dönemde Kızılırmak kavsindeki Kırıkkale’de 1925–1932 arasında mühimmat, pirinç, elektrik makineleri, çelik ve barut tesisleri kuruldu; 1925–1926 yıllarında ise Yavuz zırhlısının onarımı ve donanma üssü için Gölcük Tersanesi’nin temeli atıldı.",
      "impact": "Kayseri Uçak Fabrikası 1930’lardan itibaren lisans altında Curtiss Hawk, Curtiss Fledgling ve Polonya PZL P.24 tipi uçaklar üreterek hava kuvvetlerinin bakım ve montaj üssüne dönüştü. Kırıkkale tesisleri kovan, fişek, mermi ve özel çelik üretiminde ordunun dışa bağımlılığını azalttı ve 1950’de Makine ve Kimya Endüstrisi Kurumu (MKEK) çatısı altında birleşecek çekirdeği oluşturdu; Gölcük Tersanesi ise donanmanın ana onarım üssüne dönüştü. Bununla birlikte TOMTAŞ deneyiminin kesintiye uğraması, motor ve ham madde teknolojisinde dış lisans ile yabancı uzman gereksiniminin bu dönemde tamamen aşılamadığını göstermektedir.",
